{"query": "
SELECT table_schema, table_name 
FROM information_schema.tables 
WHERE table_schema NOT IN ('pg_catalog', 'information_schema', 'auth', 'storage', 'realtime', 'extensions', 'graphql_public', 'graphql', 'pgbouncer', 'vault', 'pgsodium', 'pgsodium_masks', 'supabase_functions')
ORDER BY table_schema, table_name;
"}

{"query": "
-- Create gender_statistics table
CREATE TABLE IF NOT EXISTS employees.gender_statistics (
  gender               VARCHAR(1)     NOT NULL PRIMARY KEY,
  total_employees      INTEGER        NOT NULL,
  current_employees    INTEGER        NOT NULL,
  percentage_of_workforce DECIMAL(6,2) NOT NULL
);

COMMENT ON TABLE employees.gender_statistics IS 'Gender breakdown of total vs. currently active workforce with workforce percentage share.';
"}

{"query": "
-- Create age_group_analysis table
CREATE TABLE IF NOT EXISTS employees.age_group_analysis (
  age_group        VARCHAR(10)    NOT NULL PRIMARY KEY,
  employee_count   INTEGER        NOT NULL,
  avg_salary       DECIMAL(12,2)  NOT NULL,
  avg_tenure_days  DECIMAL(10,2)  NOT NULL
);

COMMENT ON TABLE employees.age_group_analysis IS 'Current employee distribution by age group with average salary and tenure metrics.';
"}

{"query": "
-- Create birth_month_distribution table
CREATE TABLE IF NOT EXISTS employees.birth_month_distribution (
  birth_month            INTEGER        NOT NULL PRIMARY KEY CHECK (birth_month BETWEEN 1 AND 12),
  month_name             VARCHAR(20)    NOT NULL,
  employee_count         INTEGER        NOT NULL,
  current_employee_count INTEGER        NOT NULL
);

COMMENT ON TABLE employees.birth_month_distribution IS 'Employee birth month distribution showing total vs. currently active headcount per month.';
"}

{"query": "
-- Create hiring_year_summary table
CREATE TABLE IF NOT EXISTS employees.hiring_year_summary (
  hire_year        INTEGER        NOT NULL PRIMARY KEY,
  employees_hired  INTEGER        NOT NULL,
  still_employed   INTEGER        NOT NULL,
  retention_rate   DECIMAL(6,2)   NOT NULL
);

COMMENT ON TABLE employees.hiring_year_summary IS 'Annual hiring cohort analysis with retention rates showing how many employees from each hire year remain active.';
"}
